from pathlib import Path
import collections
import hashlib
import json
import re
import subprocess
import tarfile

root=Path('/home/philip/ShaderLOD')
artifacts=root/'.local/artifacts'
out=root/'results/benchmark-workflows/evidence'
out.mkdir(exist_ok=True)
records={}
old_index=out/'index.json'
previous={}
if old_index.exists():
    previous=json.loads(old_index.read_text())
    for item in previous['files']:
        for record in json.loads((out/item['file']).read_text())['records']:
            records[record['id']]=record

def canonical(value):
    return json.dumps(value,ensure_ascii=False,sort_keys=True,separators=(',',':')).encode()

def retain(paths,raw,kind,data,semantic=None):
    identity=hashlib.sha256(raw).hexdigest()
    if identity in records:
        if kind=='authored-source' and not isinstance(records[identity].get('data'),str):records[identity]['source_text']=data
        records[identity]['paths']=sorted(set(records[identity]['paths']+paths))
        return identity
    records[identity]={'id':identity,'paths':paths,'kind':kind,'original_bytes':len(raw),'data':data,'semantic_sha256':hashlib.sha256(canonical(data if semantic is None else semantic)).hexdigest()}
    return identity

manifest=json.loads((root/'results/benchmark-workflows/manifest.json').read_text())
selected={row['path'] for row in manifest['records'] if row['path'].endswith('.json')}
for row in manifest['records']:
    p=artifacts/row['path']
    if previous and not p.exists():continue
    raw=p.read_bytes()
    assert len(raw)==row['bytes'] and hashlib.sha256(raw).hexdigest()==row['sha256'],row['path']
print('Selected evidence inventory verified',len(manifest['records']),flush=True)
telemetry=collections.defaultdict(list)
schemas=collections.Counter()
for p in sorted(artifacts.rglob('*.json')):
    if any(part.endswith('.git') or part in {'objects','refs','dependencies','mods','config','resourcepacks','shaderpacks','saves','libraries','assets'} for part in p.relative_to(artifacts).parts):
        continue
    raw=p.read_bytes()
    try:
        data=json.loads(raw)
    except (UnicodeError,json.JSONDecodeError):
        continue
    rel=p.relative_to(artifacts).as_posix()
    if not isinstance(data,dict):
        continue
    schema=str(data.get('schema','unknown'))
    schemas[schema]+=1
    if schema=='shaderlod-telemetry-v1':
        telemetry[str(p.parent.relative_to(artifacts))].append((rel,raw,data))
        continue
    keep=rel in selected or len(Path(rel).parts)==1 or (schema.startswith('shaderlod-') and any(x in schema for x in ['result','receipt','attempt','capture','analysis','close','sequence','assessment','recovery']))
    if keep:
        retain([rel],raw,'record',data)
frame_streams=0
for p in sorted(artifacts.rglob('*.jsonl')):
    raw=p.read_bytes()
    try:
        rows=[json.loads(line) for line in raw.splitlines() if line.strip()]
    except (UnicodeError,json.JSONDecodeError):
        continue
    if not rows:
        retain([p.relative_to(artifacts).as_posix()],raw,'frame-or-numerical-stream',{'encoding':'records','rows':[],'missing_reason':'empty original stream'},[])
        continue
    if not all(isinstance(row,dict) for row in rows):continue
    columns=list(rows[0])
    if all(set(row)==set(columns) for row in rows):
        data={'encoding':'columns','columns':columns,'rows':[[row[key] for key in columns] for row in rows]}
    else:
        data={'encoding':'records','rows':rows}
    retain([p.relative_to(artifacts).as_posix()],raw,'frame-or-numerical-stream',data,rows)
    frame_streams+=1
for name,items in telemetry.items():
    rows=[item[2] for item in items]
    raw=b'\n'.join(item[1] for item in items)
    columns=list(rows[0])
    data={'encoding':'records','rows':rows}
    if all(set(row)==set(columns) for row in rows):
        data={'encoding':'columns','columns':columns,'rows':[[row[key] for key in columns] for row in rows]}
    retain([item[0] for item in items],raw,'telemetry-stream',data,rows)

objects=subprocess.check_output(['git','rev-list','--objects','main'],cwd=root,text=True).splitlines()
candidates={line.split(' ',1)[0] for line in objects if ' ' in line and Path(line.split(' ',1)[1]).suffix in {'.py','.java','.gradle','.json','.glsl','.fsh','.vsh','.xml','.properties'}}
proc=subprocess.Popen(['git','cat-file','--batch'],cwd=root,stdin=subprocess.PIPE,stdout=subprocess.PIPE)
known={}
for oid in candidates:
    proc.stdin.write((oid+'\n').encode());proc.stdin.flush();header=proc.stdout.readline().decode().split()
    raw=proc.stdout.read(int(header[2]));assert proc.stdout.read(1)==b'\n'
    if header[1]=='blob':known[hashlib.sha256(raw).hexdigest()]=oid
proc.stdin.close();assert proc.wait()==0
source_map={};archives=[]
for p in sorted(artifacts.rglob('*.tar')):
    if p.name!='inputs.tar' and 'inputs' not in p.name and 'source' not in p.name:
        continue
    members=0
    with tarfile.open(p) as archive:
        for member in archive:
            name=member.name
            if not member.isfile() or not name.startswith(('src/','shaderlod_host/','benchmarks/','checks/')) and name not in {'build.gradle','settings.gradle','gradle.properties','gradle.lockfile'}:
                continue
            if Path(name).suffix not in {'.py','.java','.json','.gradle','.properties','.xml','.glsl','.fsh','.vsh'}:
                continue
            raw=archive.extractfile(member).read();identity=hashlib.sha256(raw).hexdigest();members+=1
            if identity not in source_map:
                if identity in known:
                    source_map[identity]={'sha256':identity,'blob':known[identity],'name':name}
                else:
                    retain([p.relative_to(artifacts).as_posix()+'!'+name],raw,'authored-source',raw.decode())
                    source_map[identity]={'sha256':identity,'record':identity,'name':name}
    archives.append({'path':p.relative_to(artifacts).as_posix(),'sha256':hashlib.sha256(p.read_bytes()).hexdigest(),'source_members':members})


diagnostic_logs=0
for p in artifacts.rglob('*.log'):
    raw=p.read_bytes();lines=raw.decode(errors='replace').splitlines();indices=set()
    for i,line in enumerate(lines):
        if re.search(r'error|exception|fail|refus|timeout|invalid|out.of.memory|too many|no more.*texture|dropped|overflow|cadence',line,re.I):
            indices.update(range(max(0,i-2),min(len(lines),i+3)))
    if indices:
        data={'complete_log_lines':len(lines),'excerpts':[{'line':i+1,'text':lines[i]} for i in sorted(indices)]}
        retain([p.relative_to(artifacts).as_posix()],raw,'diagnostic-excerpts',data);diagnostic_logs+=1
images=[]
for p in artifacts.rglob('*.png'):
    raw=p.read_bytes()
    if raw[:8]!=b'\x89PNG\r\n\x1a\n':continue
    images.append({'path':p.relative_to(artifacts).as_posix(),'sha256':hashlib.sha256(raw).hexdigest(),'bytes':len(raw),'width':int.from_bytes(raw[16:20],'big'),'height':int.from_bytes(raw[20:24],'big'),'bit_depth':raw[24],'color_type':raw[25]})
if images:
    raw=canonical(images);retain(['extracted-image-identities'],raw,'image-identities',images)

identity_rows=previous.get('identity_rows',[])
identity_lookup={(item['path'],item['sha256']):index for index,item in enumerate(identity_rows)}
def encode_identities(value):
    if isinstance(value,dict):
        if len(value)>8 and all(isinstance(v,str) and len(v)==64 and all(c in '0123456789abcdef' for c in v) for v in value.values()):
            indices=[]
            for path,digest in value.items():
                key=(path,digest)
                if key not in identity_lookup:
                    identity_lookup[key]=len(identity_rows);identity_rows.append({'path':path,'sha256':digest})
                indices.append(identity_lookup[key])
            return {'_identity_rows':indices}
        return {key:encode_identities(item) for key,item in value.items()}
    if isinstance(value,list):return [encode_identities(item) for item in value]
    return value
for record in records.values():
    if 'data' in record:record['data']=encode_identities(record['data'])

fragments={};serial_fragment=0
def partition(identity,value):
    global serial_fragment
    if len(json.dumps(value,ensure_ascii=False,separators=(',',':')).encode())<1450000:return {'data':value}
    def child(value):
        global serial_fragment
        serial_fragment+=1;key=identity+':part:'+str(serial_fragment)
        fragments[key]={'id':key,'paths':[],'kind':'fragment',**partition(key,value)}
        return key
    if isinstance(value,dict):return {'representation':{'type':'dict','items':[{'key':key,'id':child(item)} for key,item in value.items()]}}
    if isinstance(value,list):
        if len(value)==1:return {'representation':{'type':'list','items':[child(value[0])]}}
        step=max(1,min(100,len(value)//2))
        return {'representation':{'type':'chunks','items':[child(value[i:i+step]) for i in range(0,len(value),step)]}}
    raise ValueError('oversized scalar '+identity)
for record in records.values():
    if 'data' in record:
        data=record.pop('data');record.update(partition(record['id'],data))
records.update(fragments)
for p in out.glob('records-*.json'):p.unlink()

file_manifest=[];index=[];chunk=[];size=0;serial=0
def flush():
    global chunk,size,serial
    if not chunk:return
    serial+=1;name=f'records-{serial:03}.json';raw=json.dumps({'schema':'shaderlod-closed-evidence-v1','records':chunk},ensure_ascii=False,separators=(',',':')).encode()+b'\n'
    assert len(raw)<2*1024*1024,(name,len(raw))
    (out/name).write_bytes(raw);file_manifest.append({'file':name,'bytes':len(raw),'sha256':hashlib.sha256(raw).hexdigest()})
    for record in chunk:index.append({'id':record['id'],'paths':record['paths'],'kind':record['kind'],'file':name})
    chunk=[];size=0
for record in records.values():
    raw=json.dumps(record,ensure_ascii=False,separators=(',',':')).encode()
    if len(raw)>1900000:raise ValueError(('record needs partition',record['paths'],len(raw)))
    if chunk and size+len(raw)>1200000:flush()
    chunk.append(record);size+=len(raw)
flush()
payload={'schema':'shaderlod-closed-evidence-index-v1','records':index,'files':file_manifest,'source_recovery':list({row['sha256']:row for row in previous.get('source_recovery',[])+list(source_map.values())}.values()),'identity_rows':identity_rows,'source_archives':previous.get('source_archives',[])+archives,'diagnostic_logs_with_excerpts':diagnostic_logs,'image_identities_retained':len(images),'retention':'Compact result/receipt observations, complete numerical streams and source identities. Paths are original provenance labels, not live raw-bundle locations. Images, copied worlds, input binaries, verbose logs and HTML derivatives are superseded. This does not preserve arbitrary raw-image reanalysis or an intact original runtime bundle.','selected_manifest_records_verified':len(manifest['records']),'frame_or_numerical_streams':frame_streams,'telemetry_rows':sum(len(x) for x in telemetry.values()),'schemas_seen':dict(schemas)}
(out/'index.json').write_text(json.dumps(payload,ensure_ascii=False,separators=(',',':'))+'\n')
print({'records':len(records),'files':len(file_manifest),'bytes':sum(p.stat().st_size for p in out.glob('*.json')),'numerical_streams':frame_streams,'source_identities':len(source_map),'extra_source_records':sum('record' in v for v in source_map.values())},flush=True)
